// One event, one application, one organiser — the executor sends the words
// the approval read, verbatim, to the address the guardrail-checked row
// resolved.
//
// This node does not write any of the letter. CrowdRelay composed it when
// the action was written — the words the operator approved ride in `draft`,
// and a payload without one is refused rather than filled in here.
const e = $json;
if (!e || e.type !== 'crowdrelay.opportunity.application_requested' || e.version !== 1) {
  throw new Error('Unsupported opportunity event');
}
const d = e.data ?? {};
// Guardrails unchanged: never a paid, contractual or exclusive application.
if (d.payment_execution_allowed !== false || Number(d.application_fee_minor || 0) !== 0
    || d.requires_contract || d.exclusive) {
  throw new Error('Guardrail violation: paid/contractual/exclusive application');
}
const draft = d.draft || {};
const subject = String(draft.subject || '').trim();
const body = String(draft.body || '').trim();
// The refusal that keeps the promise: no approved words, no send.
if (!subject || !body) {
  throw new Error('application refused: no approved letter in the payload — nothing may compose one here');
}
const to = String(d.contact_email || '').trim();
if (!to.includes('@')) throw new Error('No email executor for this opportunity');
return [{ json: {
  event_id: e.id,
  action_id: d.action_id,
  opportunity_id: d.opportunity_id,
  SendTo: to,
  SendSubject: subject.slice(0, 220),
  SendBody: body,
} }];

const src=$('Validate safe application').item.json||{}; const r=$json||{}; const disposition=String(r.disposition||'');
if(disposition==='already_succeeded') return [];
if(disposition!=='claimed'||!r.claim_token) throw new Error(`Provider execution ${disposition||'unclaimed'}; fail closed to prevent duplicate external side effects`);
return [{json:{...src,claim_token:String(r.claim_token),attempt_number:Number(r.attempt_number||1)}}];
